<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Study;
use App\Domain\Study\ReadModel\StudyContestSubject;use App\Domain\Study\Repository\StudyContestSubjectRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\Catalog\Entity\PositionTaxonomyAssignmentRecord;use App\Infrastructure\Persistence\Doctrine\Catalog\Entity\PositionRecord;use App\Infrastructure\Persistence\Doctrine\Catalog\Entity\SyllabusRecord;use App\Infrastructure\Persistence\Doctrine\Catalog\Entity\SubjectRecord;use App\Infrastructure\Persistence\Doctrine\Catalog\Entity\SubjectTaxonomyAssignmentRecord;use App\Infrastructure\Persistence\Doctrine\Taxonomy\Entity\TaxonomySubjectRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineStudyContestSubjectRepository implements StudyContestSubjectRepositoryInterface { public function __construct(private readonly EntityManagerInterface $em){} public function listForPosition(string $positionId):array { $rows=$this->em->createQueryBuilder()->select('taxonomy.id AS id,taxonomy.parentId AS parentId,taxonomy.name AS name,taxonomy.level AS level,COALESCE(MAX(localSubject.selectionWeight), 1) AS selectionWeight')->from(PositionTaxonomyAssignmentRecord::class,'assignment')->innerJoin(TaxonomySubjectRecord::class,'taxonomy','WITH','taxonomy.id=assignment.taxonomySubjectId')->innerJoin(PositionRecord::class,'position','WITH','position.id=assignment.positionId')->leftJoin(SyllabusRecord::class,'syllabus','WITH','syllabus.examId=position.examId')->leftJoin(SubjectRecord::class,'localSubject','WITH','localSubject.syllabusId=syllabus.id')->leftJoin(SubjectTaxonomyAssignmentRecord::class,'localAssignment','WITH','localAssignment.subjectId=localSubject.id AND localAssignment.taxonomySubjectId=taxonomy.id')->where('assignment.positionId=:positionId')->andWhere('taxonomy.active=true')->setParameter('positionId',$positionId)->groupBy('taxonomy.id,taxonomy.parentId,taxonomy.name,taxonomy.level')->orderBy('taxonomy.level','ASC')->addOrderBy('taxonomy.name','ASC')->getQuery()->getArrayResult();return array_map(static fn(array $r)=>new StudyContestSubject((string)$r['id'],$r['parentId']===null?null:(string)$r['parentId'],(string)$r['name'],(int)$r['level'],max(0.0,(float)$r['selectionWeight'])),$rows); } }
